// Package xregistry is a read-only client for the Intropy xRegistry
// service: message, endpoint, and schema discovery over GET /export, plus
// in-memory resolution of a message reference into the wiring a component
// needs to subscribe to it.
//
// It shares a name and nothing else with internal/registry, the OCI
// registry client — different protocol, different base URL, different
// failure model. The two packages are unrelated and must not borrow each
// other's types; a rename of one is not a rename of the other.
//
// xRegistry has no message-to-channel field: the association is
// Endpoint.messagegroups (the groups allowed on an endpoint) plus
// Endpoint.channel, and the resolution join in resolve.go walks it. The
// registry declares filtering, inlining, entity-path lookups, and pagination
// out of scope, so the client sends only GET /export — no query params it
// did not see advertised.
package xregistry

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"sort"
	"strings"
)

// Client speaks to one read-only xRegistry service. Construct with New;
// methods take a context first and never retry internally — the caller
// owns timeouts and the retry policy.
type Client struct {
	base       *url.URL
	httpClient *http.Client
	userAgent  string
}

type options struct {
	httpClient *http.Client
	userAgent  string
}

// Option customises New.
type Option func(*options)

// WithHTTPClient replaces the default client. Tests inject an httptest
// transport here.
func WithHTTPClient(c *http.Client) Option {
	return func(o *options) { o.httpClient = c }
}

// WithUserAgent sets the User-Agent header on every request.
func WithUserAgent(ua string) Option {
	return func(o *options) { o.userAgent = ua }
}

// New builds a Client for the service at baseURL. The base URL must parse
// and be absolute: a relative base would make every request path a guess.
func New(baseURL string, opts ...Option) (*Client, error) {
	u, err := url.Parse(strings.TrimSuffix(baseURL, "/"))
	if err != nil {
		return nil, fmt.Errorf("parse xRegistry base URL %q: %w", baseURL, err)
	}
	if !u.IsAbs() {
		return nil, fmt.Errorf("xRegistry base URL %q is not absolute", baseURL)
	}
	o := options{httpClient: http.DefaultClient}
	for _, opt := range opts {
		opt(&o)
	}
	return &Client{base: u, httpClient: o.httpClient, userAgent: o.userAgent}, nil
}

// BaseURL reports the service root the client was built against, without
// a trailing slash.
func (c *Client) BaseURL() string { return c.base.String() }

// get issues one GET and decodes the JSON body into out. Error bodies are
// the xRegistry error document; both the transport error and the body are
// surfaced so the caller can front-load what failed.
func (c *Client) get(ctx context.Context, path string, out any) error {
	u := c.base.JoinPath(path)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return fmt.Errorf("build request for %s: %w", path, err)
	}
	req.Header.Set("Accept", "application/json")
	if c.userAgent != "" {
		req.Header.Set("User-Agent", c.userAgent)
	}
	resp, err := c.httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("GET %s: %w", u.String(), err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxBodyBytes))
	if err != nil {
		return fmt.Errorf("read %s: %w", u.String(), err)
	}
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("GET %s: registry returned %s: %s", u.String(), resp.Status, errorBody(body))
	}
	if err := json.Unmarshal(body, out); err != nil {
		return fmt.Errorf("parse %s: %w", u.String(), err)
	}
	return nil
}

// maxBodyBytes bounds a response read. The export of a registry that grew
// past this size is itself an operational problem — silently truncating a
// resolution input would be worse than failing loudly.
const maxBodyBytes = 64 << 20

// errorBody condenses an xRegistry error document ({code, detail, status})
// into one line; a body that does not parse is shown truncated as-is.
func errorBody(body []byte) string {
	var doc struct {
		Code   string `json:"code"`
		Detail string `json:"detail"`
	}
	if err := json.Unmarshal(body, &doc); err == nil && doc.Code != "" {
		if doc.Detail != "" {
			return doc.Code + ": " + doc.Detail
		}
		return doc.Code
	}
	const maxLen = 200
	s := string(body)
	if len(s) > maxLen {
		s = s[:maxLen] + "…"
	}
	return s
}

// Export fetches the complete registry document. One call, no walk: the
// service guarantees /export contains the message, endpoint, and schema
// views the CLI needs.
func (c *Client) Export(ctx context.Context) (*Export, error) {
	var doc Export
	if err := c.get(ctx, "/export", &doc); err != nil {
		return nil, fmt.Errorf("fetch xRegistry export: %w", err)
	}
	return &doc, nil
}

// DefaultMessage resolves a message's definition attributes from the doc
// view, where they live on the single implicit version.
func (m *Message) DefaultMessage() *MessageVersion {
	if len(m.Versions) == 0 {
		return nil
	}
	// Prefer an explicit default; a document without isdefault markers
	// (none this service emits) falls back to the lowest version id so the
	// result never depends on map iteration order.
	ids := make([]string, 0, len(m.Versions))
	for id := range m.Versions {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	var fallback *MessageVersion
	for _, id := range ids {
		v := m.Versions[id]
		if v.IsDefault {
			return v
		}
		if fallback == nil {
			fallback = v
		}
	}
	return fallback
}

package xregistry

import (
	"context"
	"fmt"
	"sort"
	"strings"
)

// Channel is one producing channel: the pub/sub component and topic an
// event flows through, as split from the endpoint's <pubsub>/<topic>
// channel string.
type Channel struct {
	Pubsub   string `json:"pubsub"`
	Topic    string `json:"topic"`
	Endpoint string `json:"endpoint,omitempty"`
}

// ResolvedMessage is the wiring --subscribe writes into a scaffold record:
// the message identity, its CloudEvents type, the channels the message can
// arrive on, and the schema pin.
type ResolvedMessage struct {
	// Message is the message id, which for these registries doubles as the
	// CloudEvents type — the registry constrains envelopemetadata.type to
	// the same dotted name. Type carries the envelope value verbatim; the
	// two are distinct fields so a registry that ever diverges them stays
	// representable.
	Message string `json:"message"`
	Type    string `json:"type,omitempty"`
	Group   string `json:"group"`

	// Channels is the set of producer endpoints' channels for the message's
	// group, split and sorted. Exactly one is the subscribe channel; more
	// is AmbiguousProducerError, none is NoProducerError.
	Channels []Channel `json:"channels,omitempty"`

	// DataSchema is the logical schema xid from the message definition;
	// DataSchemaURL pins the schema's default version — an immutable URL —
	// at subscribe time.
	DataSchema    string `json:"dataschema,omitempty"`
	DataSchemaURL string `json:"dataschemaurl,omitempty"`

	Envelope string `json:"envelope,omitempty"`
}

// ResolveMessage resolves one message reference — a bare message id or a
// full /messagegroups/<gid>/messages/<mid> xid — against the export
// document into subscription wiring. All joins are in memory: nothing but
// the export is fetched.
//
// The resolution the caller cannot do without: message → group → producer
// endpoints → channel split, plus dataschemaxid → default version URL.
func ResolveMessage(doc *Export, ref string) (*ResolvedMessage, error) {
	msg, group, err := findMessage(doc, ref)
	if err != nil {
		return nil, err
	}
	dflt := msg.DefaultMessage()
	if dflt == nil {
		return nil, &NoDefaultVersionError{Ref: ref, Group: group.ID}
	}

	res := &ResolvedMessage{
		Message:  msg.ID,
		Group:    group.ID,
		Envelope: dflt.Envelope,
	}
	if attr, ok := dflt.EnvelopeMetadata["type"]; ok {
		if s, ok := attr.Value.(string); ok {
			res.Type = s
		}
	}
	res.DataSchema = dflt.DataSchemaXID
	if res.DataSchema != "" {
		xid, err := DefaultSchemaVersionXID(doc, res.DataSchema)
		if err != nil {
			return nil, err
		}
		// Root-relative xid: the caller (Client.Resolve) joins it with the
		// base URL; a bare ResolveMessage on a hand-built doc keeps the xid.
		res.DataSchemaURL = xid
	}

	channels, err := producerChannels(doc, group.ID)
	if err != nil {
		return nil, err
	}
	res.Channels = channels
	return res, nil
}

// SubscribeChannel picks the one channel of a resolved message. The choice
// is the caller's only when several producers carry the group on different
// channels — the interactive pick list and the --no-input error both
// consume the full Channels list, so it is kept there.
func (r *ResolvedMessage) SubscribeChannel() (Channel, error) {
	switch len(r.Channels) {
	case 0:
		return Channel{}, &NoProducerError{Group: r.Group}
	case 1:
		return r.Channels[0], nil
	default:
		return Channel{}, &AmbiguousProducerError{Ref: r.Message, Channels: r.Channels}
	}
}

// FindMessage locates one message by reference — a bare message id
// (unique across groups) or a full /messagegroups/<gid>/messages/<mid>
// xid — and returns it with its group. Exported for display surfaces; the
// ambiguity and not-found failures are the typed errors.
func FindMessage(doc *Export, ref string) (*Message, *MessageGroup, error) {
	return findMessage(doc, ref)
}

func findMessage(doc *Export, ref string) (*Message, *MessageGroup, error) {
	if ref == "" {
		return nil, nil, fmt.Errorf("message reference is empty")
	}
	if xid, ok := strings.CutPrefix(ref, "/messagegroups/"); ok {
		gid, mid, ok := strings.Cut(xid, "/messages/")
		if !ok || gid == "" || mid == "" {
			return nil, nil, fmt.Errorf("message reference %q is not a message id or /messagegroups/<gid>/messages/<mid> xid", ref)
		}
		g, ok := doc.MessageGroups[gid]
		if !ok {
			return nil, nil, &MessageNotFoundError{Ref: ref}
		}
		m, ok := g.Messages[mid]
		if !ok {
			return nil, nil, &MessageNotFoundError{Ref: ref}
		}
		return &m, &g, nil
	}

	var found *Message
	var group *MessageGroup
	for i := range doc.MessageGroups {
		g := doc.MessageGroups[i]
		if m, ok := g.Messages[ref]; ok {
			if found != nil {
				xids := messageGroupXIDs(doc, ref)
				return nil, nil, fmt.Errorf("message reference %q is ambiguous: declared in groups %s", ref, strings.Join(xids, ", "))
			}
			mCopy, gCopy := m, g
			found, group = &mCopy, &gCopy
		}
	}
	if found == nil {
		return nil, nil, &MessageNotFoundError{Ref: ref}
	}
	return found, group, nil
}

// messageGroupXIDs names the groups carrying ref, for the ambiguity error.
func messageGroupXIDs(doc *Export, ref string) []string {
	var out []string
	for _, g := range doc.MessageGroups {
		if _, ok := g.Messages[ref]; ok {
			out = append(out, "/messagegroups/"+g.ID)
		}
	}
	sort.Strings(out)
	return out
}

// producerChannels joins the group to its producer endpoints and splits
// each channel. Endpoints whose usage omits "producer" are subscriptions
// and consumers, never the resolution answer.
func producerChannels(doc *Export, groupID string) ([]Channel, error) {
	want := "/messagegroups/" + groupID
	var channels []Channel
	for _, e := range doc.Endpoints {
		if !slicesContain(e.Usage, "producer") {
			continue
		}
		if !slicesContain(e.MessageGroups, want) {
			continue
		}
		pubsub, topic, err := SplitChannel(e.Channel)
		if err != nil {
			return nil, &ChannelFormatError{Endpoint: e.ID, Channel: e.Channel, err: err}
		}
		channels = append(channels, Channel{Pubsub: pubsub, Topic: topic, Endpoint: e.ID})
	}
	sort.Slice(channels, func(i, j int) bool {
		if channels[i].Pubsub != channels[j].Pubsub {
			return channels[i].Pubsub < channels[j].Pubsub
		}
		return channels[i].Topic < channels[j].Topic
	})
	return channels, nil
}

// Resolve fetches the export and resolves one message reference into
// subscription wiring — the flow --subscribe runs. The schema pin is
// returned absolute: the pinned version URL must survive on its own once
// the record is committed, so it is joined with the base URL here.
func (c *Client) Resolve(ctx context.Context, ref string) (*ResolvedMessage, error) {
	doc, err := c.Export(ctx)
	if err != nil {
		return nil, err
	}
	res, err := ResolveMessage(doc, ref)
	if err != nil {
		return nil, err
	}
	if res.DataSchemaURL != "" {
		if u, err := c.base.Parse(strings.TrimPrefix(res.DataSchemaURL, "/")); err == nil {
			res.DataSchemaURL = u.String()
		}
	}
	return res, nil
}

// SplitChannel splits an endpoint channel into its pub/sub component and
// topic halves. The format belongs to the registry's conformance suite;
// this validates and fails naming the endpoint rather than accepting a
// half-parsed channel.
func SplitChannel(channel string) (pubsub, topic string, err error) {
	pubsub, topic, ok := strings.Cut(channel, "/")
	if !ok || strings.TrimSpace(pubsub) == "" || strings.TrimSpace(topic) == "" {
		return "", "", fmt.Errorf("channel %q is not <pubsub>/<topic>", channel)
	}
	return pubsub, topic, nil
}

// DefaultSchemaVersionXID pins a logical schema xid to its default
// version's xid — the immutable form a CloudEvent dataschema references.
// Exported for callers that already hold the export document and resolve
// display data (URLs, names) without a second round-trip.
func DefaultSchemaVersionXID(doc *Export, xid string) (string, error) {
	gid, sid, ok := splitSchemaXID(xid)
	if !ok {
		return "", &SchemaNotFoundError{XID: xid}
	}
	g, ok := doc.SchemaGroups[gid]
	if !ok {
		return "", &SchemaNotFoundError{XID: xid}
	}
	s, ok := g.Schemas[sid]
	if !ok {
		return "", &SchemaNotFoundError{XID: xid}
	}
	for _, v := range s.Versions {
		if v.IsDefault {
			return v.XID, nil
		}
	}
	return "", &SchemaNotFoundError{XID: xid}
}

// splitSchemaXID parses /schemagroups/<gid>/schemas/<sid>.
func splitSchemaXID(xid string) (gid, sid string, ok bool) {
	rest, ok := strings.CutPrefix(xid, "/schemagroups/")
	if !ok {
		return "", "", false
	}
	gid, sid, ok = strings.Cut(rest, "/schemas/")
	if !ok || gid == "" || sid == "" {
		return "", "", false
	}
	return gid, sid, true
}

func slicesContain(list []string, want string) bool {
	for _, s := range list {
		if s == want {
			return true
		}
	}
	return false
}

package xregistry

// The served subset of the xRegistry 1.0-rc2x document model, decoded from
// GET /export. The registry is API-only and read-only (the service refuses
// filtering, inlining, and pagination), so the whole model arrives in one
// document and all resolution joins happen in memory against it.
//
// /export is the doc view: references are root-relative xids, collection
// urls and counts are absent, and for hasdocument resources the default
// Version's attributes are NOT repeated on the Resource. For messages —
// maxversions: 1 — every attribute therefore lives on the single implicit
// version, never on the message resource itself. Schemas, by contrast, are
// multi-version resources whose versions each carry isdefault.

// Export is the whole registry document from GET /export. The three
// collections are top-level group collections; an absent collection decodes
// as an empty map, so a caller never nil-checks.
type Export struct {
	SpecVersion   string                  `json:"specversion"`
	RegistryID    string                  `json:"registryid"`
	MessageGroups map[string]MessageGroup `json:"messagegroups"`
	Endpoints     map[string]Endpoint     `json:"endpoints"`
	SchemaGroups  map[string]SchemaGroup  `json:"schemagroups"`
}

// MessageGroup is one xRegistry message group carrying its message
// collection. The registry guarantees every published group is referenced
// by at least one channelled endpoint.
type MessageGroup struct {
	ID       string             `json:"messagegroupid"`
	Name     string             `json:"name,omitempty"`
	Messages map[string]Message `json:"messages"`
}

// Message is one message definition in the doc view. Definition attributes
// (envelope metadata, dataschemaxid) live on the single implicit version
// under Versions.
type Message struct {
	ID       string                     `json:"messageid"`
	Versions map[string]*MessageVersion `json:"versions"`
}

// MessageVersion is one version of a message definition. Messages have
// exactly one implicit version (versionid "1") carrying the definition.
type MessageVersion struct {
	VersionID        string                 `json:"versionid"`
	IsDefault        bool                   `json:"isdefault"`
	Envelope         string                 `json:"envelope,omitempty"`
	EnvelopeMetadata map[string]CEAttribute `json:"envelopemetadata,omitempty"`
	DataSchemaFormat string                 `json:"dataschemaformat,omitempty"`
	DataSchemaXID    string                 `json:"dataschemaxid,omitempty"`
	DataContentType  string                 `json:"datacontenttype,omitempty"`
}

// CEAttribute is one envelope metadata attribute. The registry constrains
// some attributes with a constant value; a message's CloudEvents type is
// the value of its `type` attribute.
type CEAttribute struct {
	Value       any    `json:"value"`
	Type        string `json:"type,omitempty"`
	Required    bool   `json:"required,omitempty"`
	Description string `json:"description,omitempty"`
}

// Endpoint is one registry endpoint: a role, the channel the endpoint
// speaks on, and the message groups allowed on it. Channel is
// <pubsub>/<topic>; the split helper in resolve.go owns the format.
type Endpoint struct {
	ID            string   `json:"endpointid"`
	Name          string   `json:"name,omitempty"`
	Usage         []string `json:"usage,omitempty"`
	Channel       string   `json:"channel,omitempty"`
	MessageGroups []string `json:"messagegroups,omitempty"`
}

// SchemaGroup is one schema group carrying schema resources.
type SchemaGroup struct {
	ID      string            `json:"schemagroupid"`
	Name    string            `json:"name,omitempty"`
	Schemas map[string]Schema `json:"schemas"`
}

// Schema is one schema resource. Versions carry isdefault; the default
// version URL is the immutable pin a CloudEvent dataschema references.
type Schema struct {
	ID       string             `json:"schemaid"`
	Format   string             `json:"format,omitempty"`
	Versions map[string]Version `json:"versions"`
}

// Version is one immutable schema version. XID is root-relative; the
// pinned URL is the base URL joined with it.
type Version struct {
	VersionID string `json:"versionid"`
	XID       string `json:"xid,omitempty"`
	IsDefault bool   `json:"isdefault"`
}

package xregistry

import (
	"fmt"
	"strings"
)

// The typed resolution failures. Each names the entity it failed on so the
// command layer can map them to the CLI error voice — front-loaded
// failure, remediation on the second line — without re-parsing strings.

// MessageNotFoundError reports a reference that matched no message.
type MessageNotFoundError struct{ Ref string }

func (e *MessageNotFoundError) Error() string {
	return fmt.Sprintf("message %q not found in the registry", e.Ref)
}

// NoProducerError reports a message group carried by no producer endpoint.
type NoProducerError struct{ Group string }

func (e *NoProducerError) Error() string {
	return fmt.Sprintf("message group %q has no producer endpoint in the registry", e.Group)
}

// AmbiguousProducerError reports several producer endpoints carrying the
// message's group on different channels. Candidates names both channels so
// an interactive run can offer the pick list a --no-input run refuses to
// choose from.
type AmbiguousProducerError struct {
	Ref      string
	Channels []Channel
}

func (e *AmbiguousProducerError) Error() string {
	var parts []string
	for _, c := range e.Channels {
		parts = append(parts, c.Pubsub+"/"+c.Topic)
	}
	return fmt.Sprintf("message %q is produced on %d channels: %s", e.Ref, len(e.Channels), strings.Join(parts, ", "))
}

// ChannelFormatError reports a channel the <pubsub>/<topic> split rejects;
// the channel format belongs to the registry's conformance suite, and a
// half-parsed channel must not become wiring.
type ChannelFormatError struct {
	Endpoint string
	Channel  string
	err      error
}

func (e *ChannelFormatError) Error() string {
	return fmt.Sprintf("endpoint %s: %v", e.Endpoint, e.err)
}

func (e *ChannelFormatError) Unwrap() error { return e.err }

// SchemaNotFoundError reports a message's dataschemaxid that resolves to no
// schema default version in the export.
type SchemaNotFoundError struct{ XID string }

func (e *SchemaNotFoundError) Error() string {
	return fmt.Sprintf("schema %q not found in the registry", e.XID)
}

// NoDefaultVersionError reports a message whose definition carries no
// attributes on any version — a registry document the client does not
// understand, not a wiring the CLI can guess.
type NoDefaultVersionError struct {
	Ref   string
	Group string
}

func (e *NoDefaultVersionError) Error() string {
	return fmt.Sprintf("message %q in group %q carries no definition attributes", e.Ref, e.Group)
}

package main

import (
	"sort"

	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
	"github.com/spf13/cobra"
)

// messageCmd groups the read-only discovery surface for messages: what the
// read-only xRegistry serves, plus what the workspace's scaffold records
// declare through publishes blocks. It never writes anything.
var messageCmd = &cobra.Command{
	Use:   "message",
	Short: "Discover registry and workspace messages",
	Long: "Discover messages. 'message list' merges the read-only xRegistry with the messages the workspace's scaffold records declare through publishes blocks; " +
		"'message show <ref>' prints one message's definition. Reading the registry requires registryUrl to be configured — there is no default",
}

// resolveRegistryURL layers the --registry-url flag over the config, the
// same precedence every other setting uses.
func resolveRegistryURL(flagURL string) (string, error) {
	cfg, err := config.Load()
	if err != nil {
		return "", err
	}
	url, err := cfg.Resolve(config.Flags{RegistryURL: flagURL}).RequireRegistryURL()
	if err != nil {
		return "", newUsageErrorf("%v", err)
	}
	return url, nil
}

// registryClient builds the xRegistry client from the resolved
// --registry-url. An unconfigured registry is a usage error naming every
// way to set it; there is no guessed default.
func registryClient(flagURL string) (*xregistry.Client, error) {
	url, err := resolveRegistryURL(flagURL)
	if err != nil {
		return nil, err
	}
	return xregistry.New(url, xregistry.WithUserAgent("intropy-cli/"+version))
}

// workspaceMessages indexes the publishes declarations under dir. Scan and
// parse warnings are non-fatal: a malformed sibling record must not hide
// the messages the rest of the workspace declares.
func workspaceMessages(dir string, warnf func(error)) []MessageEntry {
	entries, warnings := template.ListScaffolds(dir)
	for _, w := range warnings {
		warnf(w)
	}
	seen := map[string]bool{}
	var out []MessageEntry
	for _, e := range entries {
		pub, err := template.ReadPublishesBlock(e)
		if err != nil || pub == nil {
			// Malformed block: skipped here — listing must show what is
			// resolvable; assembly is the surface that reports the record.
			continue
		}
		if seen[pub.Message] {
			continue
		}
		seen[pub.Message] = true
		out = append(out, MessageEntry{
			Message:  pub.Message,
			Source:   messageSourceWorkspace,
			Type:     pub.Message,
			Contract: pub.Contract,
			Path:     e.Path,
		})
	}
	sortMessageEntries(out)
	return out
}

// sortMessageEntries orders a merged list: registry messages by ref, then
// workspace messages by name — the stable order both table and JSON echo.
func sortMessageEntries(entries []MessageEntry) {
	sort.SliceStable(entries, func(i, j int) bool {
		if entries[i].Source != entries[j].Source {
			return entries[i].Source == messageSourceRegistry
		}
		return entries[i].Message < entries[j].Message
	})
}

func init() {
	rootCmd.AddCommand(messageCmd)
}

package main

// The registry half of the message commands: parse the export document
// into the shared MessageEntry shape. All joins happen in memory against
// one GET /export — the registry declares filtering and per-entity reverse
// lookups out of scope, so there is nothing smaller to fetch.

import (
	"context"
	"fmt"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

const (
	messageSourceRegistry  = "registry"
	messageSourceWorkspace = "workspace"
)

// registryMessages reads the export into entries, optionally narrowed to
// one group. Resolution failures that block wiring (an ambiguous or
// unreachable subscription channel) do not block listing: the table shows
// the channels it can see.
func registryMessages(ctx context.Context, client *xregistry.Client, group string) ([]MessageEntry, error) {
	doc, err := client.Export(ctx)
	if err != nil {
		return nil, err
	}

	ids := make([]string, 0, len(doc.MessageGroups))
	for id := range doc.MessageGroups {
		ids = append(ids, id)
	}
	sort.Strings(ids)

	var out []MessageEntry
	for _, gid := range ids {
		g := doc.MessageGroups[gid]
		if group != "" && gid != group {
			continue
		}
		for _, mid := range sortedMessageIDs(g) {
			m := g.Messages[mid]
			def := m.DefaultMessage()
			if def == nil {
				continue
			}
			e := MessageEntry{
				Message:  m.ID,
				Source:   messageSourceRegistry,
				Group:    gid,
				Type:     envelopeType(def),
				Envelope: def.Envelope,
				Channels: producerChannels(doc, gid),
			}
			if def.DataSchemaXID != "" {
				e.DataSchema = def.DataSchemaXID
				e.DataSchemaName = schemaName(def.DataSchemaXID)
				if xid, err := xregistry.DefaultSchemaVersionXID(doc, def.DataSchemaXID); err == nil {
					e.DataSchemaURL = joinURL(client.BaseURL(), xid)
				}
			}
			e.EnvelopeMeta = envelopeMetadata(def)
			out = append(out, e)
		}
	}
	return out, nil
}

// registryMessage finds exactly one message by reference — bare message id
// or /messagegroups/<gid>/messages/<mid> xid — for `message show`.
func registryMessage(ctx context.Context, client *xregistry.Client, ref string) (*MessageEntry, error) {
	doc, err := client.Export(ctx)
	if err != nil {
		return nil, err
	}
	msg, group, err := xregistry.FindMessage(doc, ref)
	if err != nil {
		return nil, err
	}
	def := msg.DefaultMessage()
	if def == nil {
		return nil, fmt.Errorf("message %q in group %s carries no definition attributes", ref, group.ID)
	}
	e := &MessageEntry{
		Message:  msg.ID,
		Source:   messageSourceRegistry,
		Group:    group.ID,
		Type:     envelopeType(def),
		Envelope: def.Envelope,
		Channels: producerChannels(doc, group.ID),
	}
	if def.DataSchemaXID != "" {
		e.DataSchema = def.DataSchemaXID
		e.DataSchemaName = schemaName(def.DataSchemaXID)
		if xid, err := xregistry.DefaultSchemaVersionXID(doc, def.DataSchemaXID); err == nil {
			e.DataSchemaURL = joinURL(client.BaseURL(), xid)
		}
	}
	e.EnvelopeMeta = envelopeMetadata(def)
	return e, nil
}

func sortedMessageIDs(g xregistry.MessageGroup) []string {
	ids := make([]string, 0, len(g.Messages))
	for id := range g.Messages {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

// producerChannels lists the producer endpoints' channels for one group,
// split-validated and rendered as <pubsub>/<topic>. A malformed channel is
// skipped here: listing must show what is resolvable, and assembly or
// --subscribe is the surface that reports the malformed endpoint.
func producerChannels(doc *xregistry.Export, groupID string) []string {
	want := "/messagegroups/" + groupID
	var out []string
	for _, e := range doc.Endpoints {
		if !usageHas(e.Usage, "producer") || !usageHas(e.MessageGroups, want) {
			continue
		}
		if pubsub, topic, err := xregistry.SplitChannel(e.Channel); err == nil {
			out = append(out, pubsub+"/"+topic)
		}
	}
	sort.Strings(out)
	return out
}

func usageHas(list []string, want string) bool {
	for _, s := range list {
		if s == want {
			return true
		}
	}
	return false
}

// envelopeType extracts the CloudEvents type from the envelope metadata.
func envelopeType(def *xregistry.MessageVersion) string {
	if attr, ok := def.EnvelopeMetadata["type"]; ok {
		if s, ok := attr.Value.(string); ok {
			return s
		}
	}
	return ""
}

// envelopeMetadata renders the envelope attributes sorted by name so the
// JSON document is stable across exports.
func envelopeMetadata(def *xregistry.MessageVersion) []kvHolder {
	names := make([]string, 0, len(def.EnvelopeMetadata))
	for n := range def.EnvelopeMetadata {
		names = append(names, n)
	}
	sort.Strings(names)
	out := make([]kvHolder, 0, len(names))
	for _, n := range names {
		a := def.EnvelopeMetadata[n]
		kv := kvHolder{Name: n, Required: a.Required}
		if s, ok := a.Value.(string); ok {
			kv.Value = s
		} else if a.Value != nil {
			kv.Value = fmt.Sprint(a.Value)
		}
		out = append(out, kv)
	}
	return out
}

// schemaName renders the schema xid's resource tail for the table column.
func schemaName(xid string) string {
	if i := strings.LastIndex(xid, "/schemas/"); i >= 0 {
		rest := xid[i+len("/schemas/"):]
		if j := strings.Index(rest, "/"); j >= 0 {
			return rest[:j]
		}
		return rest
	}
	return xid
}

// joinURL joins the registry base URL with a root-relative xid.
func joinURL(base, xid string) string {
	return strings.TrimSuffix(base, "/") + xid
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"text/tabwriter"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/spf13/cobra"
)

type messageListFlags struct {
	output      string
	group       string
	registryURL string
}

var messageListOpts messageListFlags

var messageListCmd = &cobra.Command{
	Use:   "list [dir]",
	Short: "List messages from the registry and this workspace",
	Long: "List messages: every message the read-only xRegistry serves, merged with the messages this workspace's scaffold records declare through publishes blocks. " +
		"Reads " + template.ScaffoldRelPath + " under dir (default: the current directory) and one GET against the registry. " +
		"Use --group to narrow to one registry message group; workspace messages have no group and are hidden by the filter. " +
		"Use --output json for a machine-readable document including envelope metadata and producing channels.",
	Args: usageArgs(cobra.MaximumNArgs(1)),
	RunE: func(cmd *cobra.Command, args []string) error {
		if err := validateOutputFlag(messageListOpts.output, "json", "plain"); err != nil {
			return err
		}
		dir := "."
		if len(args) == 1 {
			dir = args[0]
		}
		if info, err := os.Stat(dir); err != nil {
			return fmt.Errorf("message list: %w", err)
		} else if !info.IsDir() {
			return newUsageErrorf("message list: %s is not a directory", dir)
		}

		stderr := cmd.ErrOrStderr()
		var entries []MessageEntry
		if messageListOpts.group == "" {
			entries = append(entries, workspaceMessages(dir, func(w error) {
				fmt.Fprintln(stderr, "warning:", w)
			})...)
		}
		client, err := registryClient(messageListOpts.registryURL)
		if err != nil {
			return err
		}
		registryEntries, err := registryMessages(cmd.Context(), client, messageListOpts.group)
		if err != nil {
			return err
		}
		entries = append(entries, registryEntries...)

		if messageListOpts.output == "json" {
			if entries == nil {
				entries = []MessageEntry{}
			}
			enc := json.NewEncoder(cmd.OutOrStdout())
			enc.SetIndent("", "  ")
			return enc.Encode(entries)
		}

		if len(entries) == 0 {
			fmt.Fprintln(cmd.ErrOrStderr(), "no messages found")
			return nil
		}

		tw := tabwriter.NewWriter(cmd.OutOrStdout(), 0, 0, 2, ' ', 0)
		fmt.Fprintln(tw, "MESSAGE\tSOURCE\tGROUP\tCHANNEL\tSCHEMA")
		for _, e := range entries {
			channel := strings.Join(e.Channels, ", ")
			if channel == "" {
				channel = "-"
			}
			schema := e.DataSchemaName
			if schema == "" {
				schema = "-"
			}
			fmt.Fprintf(tw, "%s\t%s\t%s\t%s\t%s\n", e.Message, e.Source, e.Group, channel, schema)
		}
		return tw.Flush()
	},
}

func init() {
	f := messageListCmd.Flags()
	f.StringVarP(&messageListOpts.output, "output", "o", "plain", flagUsageOutput)
	f.StringVar(&messageListOpts.group, "group", "", "only registry messages in this message group")
	f.StringVar(&messageListOpts.registryURL, "registry-url", "", flagUsageRegistryURL)
	messageCmd.AddCommand(messageListCmd)
}

