	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
	"github.com/spf13/cobra"
)

type createFlags struct {
	outDir          string
	output          string
	name            string
	templateVersion string
	templateRepo    string
	values          []string
	sets            []string
	force           bool
	noInput         bool
	subscribe       string
	registryURL     string
}

var intCreateFlags createFlags

var intCreateCmd = &cobra.Command{
	Use:   "create <template>",
	Short: "Create a new integration",
	Long:  "Scaffold a new integration from the official Intropy template library. The positional argument selects which template subdirectory to render (e.g. 'hello-world').",
	Args:  usageArgs(cobra.ExactArgs(1)),
	RunE: func(cmd *cobra.Command, args []string) error {
		sets, err := template.ParseSets(intCreateFlags.sets)
		if err != nil {
			return err
		}
		if intCreateFlags.output != "" && intCreateFlags.output != "json" {
			return newUsageErrorf("invalid output format %q (allowed: json)", intCreateFlags.output)
		}
		outputJSON := ""
		if intCreateFlags.output == "json" {
			outputJSON = "-"
		}
		// With no --name the output dir falls to the resolved values: a
		// template with a "name" parameter gets the kebab-cased value, the
		// same convention --name itself defaults by.
		skipOutDir := intCreateFlags.outDir == "" && intCreateFlags.name == ""
		outputDir, err := resolveCreateName(intCreateFlags.name, intCreateFlags.outDir, sets)
		if err != nil {
			return err
		}
		owner, repo, err := resolveTemplateRepo(intCreateFlags.templateRepo)
		if err != nil {
			return err
		}
		stderr := cmd.ErrOrStderr()
		// Explicit --subscribe resolves before the template fetch, so a wrong
		// or unconfigured registry is reported before a GitHub download.
		downloadRefs := !intCreateFlags.noInput && intCreateFlags.subscribe == ""
		var subscribeBlock *template.SubscribeBlock
		if intCreateFlags.subscribe != "" {
			block, err := resolveSubscribeBlock(cmd.Context(), intCreateFlags.subscribe, intCreateFlags.registryURL, intCreateFlags.noInput, stderr)
			if err != nil {
				return err
			}
			subscribeBlock = block
		}
		var messageRefs []string
		if downloadRefs {
			// Prompt-time candidates, best effort: an unreachable registry
			// degrades to facts-only suggestions. With --subscribe set the
			// same failure fails hard, inside resolveSubscribeBlock.
			refs, err := registryMessageRefs(cmd.Context(), intCreateFlags.registryURL)
			if err != nil {
				fmt.Fprintf(stderr, "warning: %v — prompt suggestions fall back to workspace messages only\n", err)
			} else {
				messageRefs = refs
			}
		}
		if skipOutDir {
			out, err := deriveOutDir(cmd.Context(), template.CreateOptions{
				Template:  args[0],
				Version:   intCreateFlags.templateVersion,
				SetValues: sets,
				Files:     intCreateFlags.values,
				NoInput:   intCreateFlags.noInput,
				Stdin:     cmd.InOrStdin(),
				Stdout:    cmd.OutOrStdout(),
				Stderr:    cmd.ErrOrStderr(),
				UserAgent: "intropy-cli/" + version,
				Owner:     owner,
				Repo:      repo,
				Subscribe: subscribeBlock,
			})
			if err != nil {
				return usageIfNoMessageParams(err)
			}
			outputDir = out
		}
		facts, warnings := system.LoadWorkspaceFacts(workspaceRootOf(outputDir))
		for _, w := range warnings {
			printWarning(stderr, w)
		}
		seedOrganization(facts)
		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()
		if err := template.Create(ctx, template.CreateOptions{
			Template:    args[0],
			OutputDir:   outputDir,
			Version:     intCreateFlags.templateVersion,
			SetValues:   sets,
			Files:       intCreateFlags.values,
			Force:       intCreateFlags.force,
			NoInput:     intCreateFlags.noInput,
			OutputJSON:  outputJSON,
			Stdin:       cmd.InOrStdin(),
			Stdout:      cmd.OutOrStdout(),
			Stderr:      stderr,
			UserAgent:   "intropy-cli/" + version,
			Owner:       owner,
			Repo:        repo,
			Facts:       facts,
			Subscribe:   subscribeBlock,
			MessageRefs: messageRefs,
		}); err != nil {
			return usageIfNoMessageParams(err)
		}
		return nil
	},
}

// seedOrganization feeds the resolved config's organization into the
// facts as the ambient default. A workspace whose records already agree
// on an organization keeps its own — specific beats ambient. A config
// that cannot be read contributes nothing rather than failing the
// create: a missing config file is the common case, and the prompt is
// the fallback the fact would have spared.
func seedOrganization(facts *template.WorkspaceFacts) {
	cfg, err := config.Load()
	if err != nil {
		return
	}
	facts.SetOrganization(cfg.Resolve(config.Flags{}).Organization)
}

// workspaceRootOf derives the directory whose scaffold records feed
// prompt-time suggestions: the parent of the output directory, which is
// where a flat workspace keeps the new component's siblings.
func workspaceRootOf(outputDir string) string {
	if outputDir == "" {
		return "."
	}
	return filepath.Dir(outputDir)
}

// printWarning reports a workspace-scan issue without failing the create —
// a malformed sibling record must not block scaffolding a new component.
func printWarning(stderr io.Writer, w error) {
	fmt.Fprintf(stderr, "warning: %v\n", w)
}

// resolveCreateName folds the -n shorthand into the set map and derives the
// output dir. -n is sugar for --set name=<v>; it also defaults the output
// dir to the kebab-cased name when -o is absent — the same normalization
// sys create applies, so a name and its kebab form are one component.
func resolveCreateName(name, output string, sets map[string]any) (string, error) {
	if name == "" {
		return output, nil
	}
	if _, ok := sets["name"]; ok {
		return "", newUsageErrorf("cannot combine --name with --set name= (they conflict)")
	}
	sets["name"] = name
	if output == "" {
		output = xstrings.ToKebabCase(name)
	}
	return output, nil
}

// deriveOutDir runs the create far enough to resolve values and returns
// the kebab-cased "name" value — the directory convention for runs that
// name neither --name nor --out-dir. A template with no "name" parameter
// leaves the run with nothing to derive from, the usage error --out-dir
// would have spared.
func deriveOutDir(ctx context.Context, opts template.CreateOptions) (string, error) {
	prep, err := template.PrepareCreate(ctx, opts)
	if err != nil {
		return "", err
	}
	defer prep.Cleanup()
	name, ok := prep.Values["name"].(string)
	if !ok || name == "" {
		return "", newUsageErrorf("--out-dir is required (template %q declares no 'name' parameter to derive it from)", opts.Template)
	}
	return xstrings.ToKebabCase(name), nil
}

func init() {
	f := intCreateCmd.Flags()
	f.StringVarP(&intCreateFlags.outDir, "out-dir", "o", "", "destination directory (defaults to the kebab-cased name)")
	f.StringVar(&intCreateFlags.output, "output", "", flagUsageOutputJSONOnly)
	_ = intCreateCmd.MarkFlagDirname("out-dir")
	f.StringVarP(&intCreateFlags.name, "name", "n", "", "integration name; sets the template's 'name' parameter and, unless --out-dir is set, becomes the output directory")
	f.StringVar(&intCreateFlags.templateVersion, "template-version", "", flagUsageTemplateVer)
	f.StringVar(&intCreateFlags.templateRepo, "template-repo", "", flagUsageTemplateRepo)
	f.StringArrayVarP(&intCreateFlags.values, "values", "f", nil, "values file in YAML/JSON (repeatable; use - to read one doc from stdin)")
	f.StringArrayVarP(&intCreateFlags.sets, "set", "s", nil, "set a value as key=value (repeatable)")
	f.BoolVar(&intCreateFlags.force, "force", false, "allow rendering into a non-empty output directory")
	f.BoolVar(&intCreateFlags.noInput, "no-input", false, flagUsageNoInput)
	f.StringVar(&intCreateFlags.subscribe, "subscribe", "", flagUsageSubscribe)
	f.StringVar(&intCreateFlags.registryURL, "registry-url", "", flagUsageRegistryURL)
	intCmd.AddCommand(intCreateCmd)
}

// resolveSubscribeBlock turns --subscribe <ref> into the record block:
// resolve the message against the registry, pin its schema's default
// version URL, and pick the producing channel. An ambiguous channel is an
// interactive pick; under --no-input it is an error listing the
// candidates. Every failure here is hard: an explicit --subscribe asked
// for this wiring.
func resolveSubscribeBlock(ctx context.Context, ref, registryURLFlag string, noInput bool, stderr io.Writer) (*template.SubscribeBlock, error) {
	url, err := resolveRegistryURL(registryURLFlag)
	if err != nil {
		return nil, err
	}
	client, err := xregistry.New(url, xregistry.WithUserAgent("intropy-cli/"+version))
	if err != nil {
		return nil, err
	}
	res, err := client.Resolve(ctx, ref)
	if err != nil {
		return nil, err
	}
	channel, err := pickSubscribeChannel(res, noInput, stderr)
	if err != nil {
		return nil, err
	}
	return &template.SubscribeBlock{
		Message:       res.Message,
		Pubsub:        channel.Pubsub,
		Topic:         channel.Topic,
		Dataschema:    res.DataSchema,
		DataschemaURL: res.DataSchemaURL,
	}, nil
}

// pickSubscribeChannel chooses among the resolved message's producing
// channels: one is taken, several prompt, several under --no-input fail
// naming every candidate.
func pickSubscribeChannel(res *xregistry.ResolvedMessage, noInput bool, stderr io.Writer) (xregistry.Channel, error) {
	channel, pickErr := res.SubscribeChannel()
	if pickErr == nil {
		return channel, nil
	}
	var amb *xregistry.AmbiguousProducerError
	if !errors.As(pickErr, &amb) || noInput {
		return channel, pickErr
	}
	prompter := template.AutoPrompter(os.Stdin, stderr, false)
	if prompter == nil {
		return channel, pickErr
	}
	suggestions := make([]string, 0, len(amb.Channels))
	for _, c := range amb.Channels {
		suggestions = append(suggestions, c.Pubsub+"/"+c.Topic)
	}
	field := template.FieldSpec{
		Name:        "channel",
		Title:       fmt.Sprintf("message %s is produced on several channels; pick one", res.Message),
		Type:        "string",
		Suggestions: suggestions,
	}
	ans, _, err := prompter.Prompt(field)
	if err != nil {
		return channel, err
	}
	picked, _ := ans.(string)
	for _, c := range amb.Channels {
		if c.Pubsub+"/"+c.Topic == picked {
			return c, nil
		}
	}
	return channel, fmt.Errorf("picked channel %q is not one of: %s", picked, strings.Join(suggestions, ", "))
}

// registryMessageRefs lists every configured registry message ref for
// prompt suggestions. An unconfigured registry is an empty candidate pool;
// internal workspace messages join through the facts, not here.
func registryMessageRefs(ctx context.Context, registryURLFlag string) ([]string, error) {
	cfg, err := config.Load()
	if err != nil {
		return nil, err
	}
	url := cfg.Resolve(config.Flags{RegistryURL: registryURLFlag}).RegistryURL
	if url == "" {
		return nil, nil
	}
	client, err := xregistry.New(url, xregistry.WithUserAgent("intropy-cli/"+version))
	if err != nil {
		return nil, err
	}
	doc, err := client.Export(ctx)
	if err != nil {
		return nil, err
	}
	var refs []string
	for _, g := range doc.MessageGroups {
		for id := range g.Messages {
			refs = append(refs, id)
		}
	}
	sort.Strings(refs)
	return refs, nil
}

// usageIfNoMessageParams maps the --subscribe gate to a usage error so an
// unsupported template/request combination exits 2, not 1.
func usageIfNoMessageParams(err error) error {
	if errors.Is(err, template.ErrNoMessageParameters) {
		return newUsageErrorf("%v", err)
	}
	return err
}

package template

import (
	"fmt"
	"path/filepath"
)

// The wiring vocabulary: the parameter names block templates record in
// their scaffold values and later commands (sys create/update, deploy,
// prompt suggestions) read back. They are CLI-owned convention, not
// manifest schema — a template that names its parameters otherwise simply
// gets no assembly or suggestions. One home so a vocabulary change has
// one diff, not a scavenger hunt.
const (
	KeyAppID        = "appId"
	KeyTopic        = "topic"
	KeyContract     = "contract"
	KeyPubsub       = "pubsub"
	KeyPort         = "port"
	KeyFromPort     = "fromPort"
	KeyToPort       = "toPort"
	KeyName         = "name"
	KeyOrganization = "organization"
	KeyProjectName  = "projectName"
	KeySystemClass  = "systemClass"

	// The message wiring blocks. The flat topic/contract/pubsub keys above
	// are superseded by these: a scaffold carries either a subscribe block
	// (what the component consumes, from the registry or a producing
	// sibling) or a publishes block (what it declares). Both shapes are
	// read everywhere; writers emit only the blocks.
	KeySubscribe     = "subscribe"
	KeyPublishes     = "publishes"
	KeyMessage       = "message"
	KeyDataschema    = "dataschema"
	KeyDataschemaURL = "dataschemaurl"

	// DefaultPubsub is the pub/sub component a record belongs to when it
	// predates the pubsub value being recorded.
	DefaultPubsub = "pubsub"
)

// RecordValue reads key from a scaffold record's values as a non-empty
// string. Missing, mistyped, and empty values are errors naming the
// record, so the user knows which project to fix. It is the strict
// regime: callers validating a workspace (system assembly) use it;
// callers offering suggestions use SoftValue instead.
func RecordValue(e ScaffoldEntry, key string) (string, error) {
	record := filepath.Join(e.Path, filepath.FromSlash(ScaffoldRelPath))
	v, ok := e.Values[key]
	if !ok {
		return "", fmt.Errorf("%s: values.%s is missing", record, key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s has type %T, expected string", record, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s is empty", record, key)
	}
	return s, nil
}

// RecordValueDefault is RecordValue with a fallback for records that
// predate the value being recorded. Only a missing key falls back; a
// present but mistyped or empty value is still an error — a record that
// names the key must say something meaningful.
func RecordValueDefault(e ScaffoldEntry, key, fallback string) (string, error) {
	if _, ok := e.Values[key]; !ok {
		return fallback, nil
	}
	return RecordValue(e, key)
}

// SoftValue reads key from a values map as a non-empty string, reporting
// false for missing, mistyped, or empty values. It is the lenient regime:
// suggestion aids and best-effort joins skip such records rather than
// failing an operation the records themselves would still allow.
func SoftValue(values map[string]any, key string) (string, bool) {
	s, ok := values[key].(string)
	if !ok || s == "" {
		return "", false
	}
	return s, true
}

// The message wiring blocks. A subscribe block names the message the
// component consumes; without pubsub/topic it is an internal subscription
// whose channel assembly resolves from the producing component. With the
// snapshot fields it is an external subscription — the registry is never
// contacted again for it.
//
// PublishesBlock declares what a component produces. Contract is the .NET
// shared-project type name, carried during the transition while host
// templates render Topics.cs from it; it is not the CloudEvents type.
type SubscribeBlock struct {
	Message       string
	Pubsub        string
	Topic         string
	Dataschema    string
	DataschemaURL string
}

// PublishesBlock is a producer's message declaration.
type PublishesBlock struct {
	Message  string
	Contract string
}

// External reports whether the subscription carries its own channel
// snapshot. External subscriptions assemble without a producer and without
// touching the registry.
func (b *SubscribeBlock) External() bool { return b.Topic != "" }

// HasSubscribeValue reports whether values carry a subscribe block. Block
// presence wins over the legacy flat keys wherever both appear — the dual
// read is a fallback, never a merge.
func HasSubscribeValue(values map[string]any) bool {
	_, ok := values[KeySubscribe]
	return ok
}

// HasPublishesValue reports whether values carry a publishes block.
func HasPublishesValue(values map[string]any) bool {
	_, ok := values[KeyPublishes]
	return ok
}

// HasMessageBlocks reports whether values use the block wiring shape at
// all. Assembly and facts treat such records as block-shaped and ignore
// their legacy flat keys.
func HasMessageBlocks(values map[string]any) bool {
	return HasSubscribeValue(values) || HasPublishesValue(values)
}

// blockMap reads one block value as the map the writers produce. The
// strict regime applies: a present block must be an object, so a mistyped
// block is an error naming the record and the block, never a silent skip.
func blockMap(e ScaffoldEntry, block string) (map[string]any, error) {
	v, ok := e.Values[block]
	if !ok {
		return nil, nil // absent is not an error; the caller decides
	}
	m, ok := v.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("%s: values.%s has type %T, expected object", recordPath(e), block, v)
	}
	return m, nil
}

// blockString reads a strict non-empty string field out of a block: mistyped
// or empty names the record and the full key path.
func blockString(e ScaffoldEntry, block, key string) (string, error) {
	m, err := blockMap(e, block)
	if err != nil {
		return "", err
	}
	v, ok := m[key]
	if !ok {
		return "", nil
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s.%s has type %T, expected string", recordPath(e), block, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s.%s is empty", recordPath(e), block, key)
	}
	return s, nil
}

// recordPath names the record in error messages, matching RecordValue.
func recordPath(e ScaffoldEntry) string {
	return filepath.Join(e.Path, filepath.FromSlash(ScaffoldRelPath))
}

// ReadSubscribeBlock strictly reads the subscribe block. The message name
// is required; the snapshot fields are each required to be non-empty
// strings when present. A record with the block and empty message is a
// broken record, not a wireless one.
func ReadSubscribeBlock(e ScaffoldEntry) (*SubscribeBlock, error) {
	if !HasSubscribeValue(e.Values) {
		return nil, nil
	}
	message, err := blockString(e, KeySubscribe, KeyMessage)
	if err != nil {
		return nil, err
	}
	if message == "" {
		return nil, fmt.Errorf("%s: values.%s.%s is missing", recordPath(e), KeySubscribe, KeyMessage)
	}
	b := &SubscribeBlock{Message: message}
	for _, f := range []struct {
		key string
		dst *string
	}{
		{KeyPubsub, &b.Pubsub},
		{KeyTopic, &b.Topic},
		{KeyDataschema, &b.Dataschema},
		{KeyDataschemaURL, &b.DataschemaURL},
	} {
		s, err := blockString(e, KeySubscribe, f.key)
		if err != nil {
			return nil, err
		}
		*f.dst = s
	}
	return b, nil
}

// ReadPublishesBlock strictly reads the publishes block. The message name
// is required; the contract is the transitional .NET type and stays
// optional for templates that no longer record it.
func ReadPublishesBlock(e ScaffoldEntry) (*PublishesBlock, error) {
	if !HasPublishesValue(e.Values) {
		return nil, nil
	}
	message, err := blockString(e, KeyPublishes, KeyMessage)
	if err != nil {
		return nil, err
	}
	if message == "" {
		return nil, fmt.Errorf("%s: values.%s.%s is missing", recordPath(e), KeyPublishes, KeyMessage)
	}
	contract, err := blockString(e, KeyPublishes, KeyContract)
	if err != nil {
		return nil, err
	}
	return &PublishesBlock{Message: message, Contract: contract}, nil
}

// SubscribeBlockValue renders the block as the values-map entry writers
// emit. Writers never add the legacy flat keys alongside it.
func SubscribeBlockValue(b *SubscribeBlock) map[string]any {
	m := map[string]any{KeyMessage: b.Message}
	if b.Pubsub != "" {
		m[KeyPubsub] = b.Pubsub
	}
	if b.Topic != "" {
		m[KeyTopic] = b.Topic
	}
	if b.Dataschema != "" {
		m[KeyDataschema] = b.Dataschema
	}
	if b.DataschemaURL != "" {
		m[KeyDataschemaURL] = b.DataschemaURL
	}
	return m
}

// PublishesBlockValue renders a publishes declaration as the values-map
// entry writers emit.
func PublishesBlockValue(b *PublishesBlock) map[string]any {
	m := map[string]any{KeyMessage: b.Message}
	if b.Contract != "" {
		m[KeyContract] = b.Contract
	}
	return m
}

